const getNewSelection = (oldSelection: Selection, prevLength: number, newLength: number): Selection => {
    const cursorPosition = oldSelection.end + (newLength - prevLength);
    return {start: cursorPosition, end: cursorPosition};
};

/**
 * Returns the new amount and selection object based on the new amount
 */
const getNewAmount = (newAmount: string, decimals: number, selection: Selection): {amount: string; selection: Selection} => {
    const newAmountTrimmed = newAmount.trim();
    // Remove spaces from the newAmount value because Safari on iOS adds spaces when pasting a copied value
    // More info: https://github.com/Expensify/App/issues/16974
    const newAmountWithoutSpaces = MoneyRequestUtils.stripSpacesFromAmount(newAmountTrimmed);
    const newAmountWithoutSpacesAndCommas = newAmountWithoutSpaces.includes('.')
        ? MoneyRequestUtils.stripCommaFromAmount(newAmountWithoutSpaces)
        : MoneyRequestUtils.replaceCommasWithPeriod(newAmountWithoutSpaces);

    if (newAmountWithoutSpacesAndCommas === '' || !MoneyRequestUtils.validateAmount(newAmountWithoutSpacesAndCommas, decimals)) {
        return {amount: '', selection};
    }

    return {amount: newAmountWithoutSpacesAndCommas, selection: getNewSelection(selection, newAmountTrimmed.length, newAmountWithoutSpacesAndCommas.length)};
};

const defaultOnFormatAmount = (amount: number, currency?: string) => CurrencyUtils.convertToFrontendAmountAsString(amount, currency ?? CONST.CURRENCY.USD);

